ject)) { $url = $this->url . '/' . $object; $date = date('Y-m-d H:i:s'); $data = $this->fss->setMethod('DELETE')->setDate($date)->setUrl($url)->deleteFolderOrFlie(); if ($data['code'] != 200) { do_action( 'qqworld-collector-log', $this->log_id, 'West FSS delete object failed ($data):', print_r($data, true) ); return false; } } return true; } public function add_could_storage_form($guid) { $this->access_service(); $this->check_bucket_exists(); require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'cloudStorage-'.$this->guid.'.php'; } } ?>